/* ===== src/js/66-empty.js ===== */
/* ==========================================================================
   Empty state: the actions are one row, or one width                styles: components/empty.css
   --------------------------------------------------------------------------
   An empty state has one action, sometimes a quiet second ("Try again", "Study offline").
   Side by side they share one width (the widest label's) while the row has room for that; when it
   does not, they stack, and every button takes the width of the widest, so a centred pair never
   reads as two ragged pills. CSS cannot ask "do both fit?", so SG.fit (05-fit.js) measures it and writes
   data-fit="row" | "stack" on .empty__actions. It re-checks when the card's width or the reader's
   text size changes. Without JS the actions are a centred row that wraps (empty.css).
   ========================================================================== */
(function (SG) {
  'use strict';

  SG.fit.register('.empty__actions', { steps: ['row', 'stack'], parts: '.btn' });
})((window.SG = window.SG || {}));
